      "content": "{\n  \"sourceCommit\": \"7158026e852f3aa6578c741e673b46d7878c92c1\",\n  \"skillVersion\": \"3.0.1\",\n  \"dshVersion\": \"0.1.2-rc.1\"\n}\n"
